<?php
require_once __DIR__.'/../../../app/bootstrap.php';
require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';
Auth::requireLogin();
$db=Database::connect();marketplace_install($db);$pageTitle='Voucher Marketplace';$error='';$success=flash('success');
$courierOptions=marketplace_rajaongkir_courier_options();
if(is_post()){
    if(!CSRF::verify()){$error='Token keamanan tidak valid.';}
    else{
        try{
            $action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
            if($action==='delete'&&$id>0){$db->prepare("DELETE FROM marketplace_vouchers WHERE id=?")->execute([$id]);marketplace_v15_log($db,'voucher.delete','voucher',$id);flash('success','Voucher dihapus.');legacy_redirect('admin/marketplace-vouchers/index.php');}
            if($action==='toggle'&&$id>0){$db->prepare("UPDATE marketplace_vouchers SET is_active=IF(is_active=1,0,1),updated_at=NOW() WHERE id=?")->execute([$id]);marketplace_v15_log($db,'voucher.toggle','voucher',$id);flash('success','Status voucher diperbarui.');legacy_redirect('admin/marketplace-vouchers/index.php');}
            $code=strtoupper(trim((string)($_POST['code']??'')));$name=trim((string)($_POST['name']??''));
            $benefit=in_array((string)($_POST['benefit_type']??'order'),['order','shipping'],true)?(string)$_POST['benefit_type']:'order';
            $type=(string)($_POST['discount_type']??'fixed');$value=max(0,(float)($_POST['discount_value']??0));$min=max(0,(float)($_POST['min_purchase']??0));$max=max(0,(float)($_POST['max_discount']??0));$limit=max(0,(int)($_POST['usage_limit']??0));
            $starts=trim((string)($_POST['starts_at']??''))?:null;$ends=trim((string)($_POST['ends_at']??''))?:null;$active=((string)($_POST['is_active']??'0'))==='1'?1:0;
            $couriers=[];foreach((array)($_POST['courier_codes']??[]) as $c){$c=strtolower(trim((string)$c));if(isset($courierOptions[$c]))$couriers[]=$c;}$courierCodes=implode(',',array_values(array_unique($couriers)));
            if(!preg_match('/^[A-Z0-9_-]{3,40}$/',$code))throw new InvalidArgumentException('Kode voucher minimal 3 karakter, hanya huruf/angka/_/-.');
            if($name==='')throw new InvalidArgumentException('Nama voucher wajib diisi.');if(!in_array($type,['fixed','percent'],true))$type='fixed';if($type==='percent'&&$value>100)throw new InvalidArgumentException('Diskon persen maksimal 100%.');
            if($benefit==='shipping'&&$value<=0)throw new InvalidArgumentException('Nilai subsidi gratis ongkir harus lebih dari 0.');
            if($id>0){$stmt=$db->prepare("UPDATE marketplace_vouchers SET code=?,name=?,benefit_type=?,discount_type=?,discount_value=?,min_purchase=?,max_discount=?,courier_codes=?,usage_limit=?,starts_at=?,ends_at=?,is_active=?,updated_at=NOW() WHERE id=?");$stmt->execute([$code,$name,$benefit,$type,$value,$min,$max,$courierCodes?:null,$limit,$starts,$ends,$active,$id]);}
            else{$stmt=$db->prepare("INSERT INTO marketplace_vouchers(code,name,benefit_type,discount_type,discount_value,min_purchase,max_discount,courier_codes,usage_limit,used_count,starts_at,ends_at,is_active,created_at) VALUES(?,?,?,?,?,?,?,?,?,0,?,?,?,NOW())");$stmt->execute([$code,$name,$benefit,$type,$value,$min,$max,$courierCodes?:null,$limit,$starts,$ends,$active]);$id=(int)$db->lastInsertId();}
            marketplace_v15_log($db,'voucher.save','voucher',$id,$code.' / '.$benefit);flash('success',$id>0?'Voucher berhasil disimpan.':'Voucher dibuat.');legacy_redirect('admin/marketplace-vouchers/index.php');
        }catch(Throwable $e){$error=$e->getMessage();}
    }
}
$edit=null;if(isset($_GET['edit'])){$stmt=$db->prepare("SELECT * FROM marketplace_vouchers WHERE id=? LIMIT 1");$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch()?:null;}
$selectedCouriers=array_filter(array_map('trim',explode(',',strtolower((string)($edit['courier_codes']??'')))));
$page=max(1,(int)($_GET['page']??1));$per=20;$total=(int)$db->query("SELECT COUNT(*) FROM marketplace_vouchers")->fetchColumn();$meta=pagination_meta($total,$page,$per);$rows=$db->query("SELECT * FROM marketplace_vouchers ORDER BY id DESC LIMIT {$meta['perPage']} OFFSET {$meta['offset']}")->fetchAll()?:[];
require __DIR__.'/../../layouts/admin-header.php';require __DIR__.'/../../layouts/admin-sidebar.php';
?>
<link rel="stylesheet" href="<?=legacy_base_url('assets/css/marketplace-customer-admin.css?v=15')?>">
<main class="admin-main mp-admin"><header class="admin-topbar page-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1>Voucher Marketplace</h1><p>Diskon belanja dan subsidi gratis ongkir terpisah dari promo POS.</p></div></header>
<?php if($success):?><div class="mp-alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="mp-alert error"><?=e($error)?></div><?php endif;?>
<section class="mp-admin-grid"><section class="mp-panel"><div class="mp-panel-head"><div><h3><?=$edit?'Edit Voucher':'Voucher Baru'?></h3><p>Semua nilai diverifikasi ulang server saat checkout.</p></div></div>
<form method="post" class="mp-form"><?=CSRF::input()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>">
<label>Kode Voucher<input name="code" required maxlength="40" value="<?=e($edit['code']??'')?>" placeholder="FREEONGKIR"></label><label>Nama Voucher<input name="name" required value="<?=e($edit['name']??'')?>" placeholder="Gratis ongkir September"></label>
<div class="mp-form-grid"><label>Manfaat<select name="benefit_type"><option value="order" <?=($edit['benefit_type']??'order')==='order'?'selected':''?>>Diskon Belanja</option><option value="shipping" <?=($edit['benefit_type']??'')==='shipping'?'selected':''?>>Gratis / Subsidi Ongkir</option></select></label><label>Tipe Nilai<select name="discount_type"><option value="fixed" <?=($edit['discount_type']??'')==='fixed'?'selected':''?>>Nominal</option><option value="percent" <?=($edit['discount_type']??'')==='percent'?'selected':''?>>Persen</option></select></label><label>Nilai<input type="number" min="0" step="0.01" name="discount_value" required value="<?=e($edit['discount_value']??0)?>"></label><label>Minimum Belanja<input type="number" min="0" step="1" name="min_purchase" value="<?=e($edit['min_purchase']??0)?>"></label><label>Maks. Diskon/Subsidi <small>0 = tanpa batas</small><input type="number" min="0" step="1" name="max_discount" value="<?=e($edit['max_discount']??0)?>"></label><label>Kuota <small>0 = tanpa batas</small><input type="number" min="0" name="usage_limit" value="<?=e($edit['usage_limit']??0)?>"></label><label>Status<select name="is_active"><option value="1" <?=!isset($edit['is_active'])||$edit['is_active']?'selected':''?>>Aktif</option><option value="0" <?=isset($edit['is_active'])&&!$edit['is_active']?'selected':''?>>Nonaktif</option></select></label><label>Mulai<input type="datetime-local" name="starts_at" value="<?=!empty($edit['starts_at'])?e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):''?>"></label><label>Berakhir<input type="datetime-local" name="ends_at" value="<?=!empty($edit['ends_at'])?e(date('Y-m-d\TH:i',strtotime($edit['ends_at']))):''?>"></label></div>
<div class="mp-panel" style="margin:14px 0"><div class="mp-panel-head"><div><h4>Ekspedisi Gratis Ongkir</h4><p>Khusus voucher ongkir. Tidak ada yang dicentang = berlaku ke semua ekspedisi aktif.</p></div></div><div class="mp-toggle-grid"><?php foreach($courierOptions as $code=>$label):?><label class="mp-check"><input type="checkbox" name="courier_codes[]" value="<?=e($code)?>" <?=in_array($code,$selectedCouriers,true)?'checked':''?>> <?=e($label)?></label><?php endforeach;?></div></div>
<button class="mp-btn primary" type="submit"><i class="bi bi-save"></i> Simpan Voucher</button><?php if($edit):?><a class="mp-btn soft" href="<?=legacy_base_url('admin/marketplace-vouchers/index.php')?>">Batal Edit</a><?php endif;?></form></section>
<section class="mp-panel mp-list-panel"><div class="mp-panel-head"><div><h3>Daftar Voucher</h3><p><?=$total?> voucher marketplace.</p></div></div><div class="mp-table-wrap"><table class="mp-table"><thead><tr><th>Voucher</th><th>Manfaat</th><th>Nilai</th><th>Syarat</th><th>Pemakaian</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if($rows):foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b><small><?=e($r['name'])?></small></td><td><span class="mp-badge <?=($r['benefit_type']??'order')==='shipping'?'purple':'blue'?>"><?=($r['benefit_type']??'order')==='shipping'?'Gratis Ongkir':'Diskon Belanja'?></span><?php if(($r['benefit_type']??'order')==='shipping'&&!empty($r['courier_codes'])):?><small><?=e(strtoupper(str_replace(',',', ',$r['courier_codes'])))?></small><?php endif;?></td><td><b><?=$r['discount_type']==='percent'?e(rtrim(rtrim(number_format($r['discount_value'],2,'.',''),'0'),'.')).'%':rupiah($r['discount_value'])?></b><small>Maks: <?=$r['max_discount']>0?rupiah($r['max_discount']):'Tanpa batas'?></small></td><td>Min. <?=rupiah($r['min_purchase'])?></td><td><?=e($r['used_count'])?> / <?=$r['usage_limit']>0?e($r['usage_limit']):'∞'?></td><td><span class="mp-badge <?=$r['is_active']?'green':'gray'?>"><?=$r['is_active']?'Aktif':'Off'?></span></td><td><div class="mp-actions"><a href="?edit=<?=$r['id']?>" class="mp-icon"><i class="bi bi-pencil"></i></a><form method="post"><?=CSRF::input()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="mp-icon"><i class="bi bi-power"></i></button></form><form method="post" onsubmit="return confirm('Hapus voucher ini?')"><?=CSRF::input()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="mp-icon danger"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;else:?><tr><td colspan="7" class="empty">Belum ada voucher marketplace.</td></tr><?php endif;?></tbody></table></div><?php if($meta['lastPage']>1):?><nav class="mp-pagination"><?php for($i=1;$i<=$meta['lastPage'];$i++):?><a class="<?=$i===$meta['page']?'active':''?>" href="?page=<?=$i?>"><?=$i?></a><?php endfor;?></nav><?php endif;?></section></section></main>
